const ANSI = /\u001b\[[0-?]*[ -/]*[@-~]|\u001b\][^\u0007\u001b]*(?:\u0007|\u001b\x5c)/g

export function stripAnsi(text: string): string {
  return text.replace(ANSI, '')
}

export function normalizeNewlines(text: string): string {
